@app.route("/filedata")
def getFileData():
    import os
    from werkzeug.utils import secure_filename

    filename = request.args.get("filename")
    if not filename:
        return "Filename is required", 400

    if (
        filename in (".", "..")
        or filename.startswith(".")
        or ".." in filename
        or os.path.sep in filename
        or (os.path.altsep and os.path.altsep in filename)
        or os.path.basename(filename) != filename
        or "\x00" in filename
        or any(ord(c) < 32 for c in filename)
    ):
        return "Invalid filename", 400

    safe_filename = secure_filename(filename)
    if not safe_filename:
        return "Invalid filename", 400

    config_root = app.config.get("FILE_ROOT") or app.config.get("UPLOAD_FOLDER")
    if config_root:
        base_dirs = [os.path.realpath(config_root)]
    else:
        base_dirs = [os.path.realpath(app.root_path), os.path.realpath(os.getcwd())]

    file_path = None
    for base_dir in base_dirs:
        for candidate_name in (filename, safe_filename):
            candidate_path = os.path.realpath(os.path.join(base_dir, candidate_name))
            try:
                if os.path.commonpath([base_dir, candidate_path]) != base_dir:
                    continue
            except ValueError:
                continue

            if os.path.isfile(candidate_path):
                file_path = candidate_path
                break

        if file_path is not None:
            break

    if file_path is None:
        return "File not found", 404

    try:
        with open(file_path, "rb") as file:
            data = file.read()
        return data, 200, {"Content-Type": "application/octet-stream"}
    except OSError:
        return "Unable to read file", 500

